      result[left] = this._sums[node];
      return;
    }
    this._push(node, left, right);
    const middle = Math.floor((left + right) / 2);
    this._write(node * 2, left, middle, result);
    this._write(node * 2 + 1, middle, right, result);
  }
}

module.exports = { RangeTree };

